    if sandbox.get_checkpoint_reached():
        # Move towards final target zone
        target_center = (28.0, 2.5)
        dx = target_center[0] - x
        dy = target_center[1] - y
        length = math.hypot(dx, dy)
        if length == 0:
            sandbox.apply_thrust(0, 0)
        else:
            dir_x = dx / length
            dir_y = dy / length
            # Apply thrust to move towards target
            if math.hypot(vx, vy) < 0.1:
                # Apply maximum thrust when not moving
                sandbox.apply_thrust(50.0 * dir_x, 50.0 * dir_y)
